  ArrayList<Integer> result = new ArrayList<>();
  int row = 0, col = 0;
  boolean up = true;

  for (int i = 0; i < N * M; i++) {
    result.add(mat[row][col]);
    if (up) {
      if (col == M - 1) {
        row++;
        up = false;
      } else if (row == 0) {
        col++;
        up = false;
      } else {
        row--;
        col++;
      }
    } else {
      if (row == N - 1) {
        col++;
        up = true;
      } else if (col == 0) {
        row++;
        up = true;
      } else {
        row++;
        col--;
      }
    }
  }

  return result.stream().mapToInt(i -> i).toArray();
}

