public static int findSmallestInteger(int n) {
    // Convert the integer to a char array representing its digits
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Step 1: Find the first index from the end where digits[i] < digits[i+1]
    int pivot = len - 2;
    while (pivot >= 0 && digits[pivot] >= digits[pivot + 1]) {
        pivot--;
    }

    // If no pivot found, the digits are in the highest possible order
    if (pivot < 0) {
        return -1;
    }

    // Step 2: Find the smallest digit on the right side of the pivot that is greater than digits[pivot]
    int successor = len - 1;
    while (digits[successor] <= digits[pivot]) {
        successor--;
    }

    // Step 3: Swap the pivot with the successor
    char temp = digits[pivot];
    digits[pivot] = digits[successor];
    digits[successor] = temp;

    // Step 4: Reverse the suffix starting at pivot + 1
    int left = pivot + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert back to integer and check for overflow
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        // Overflow: the next permutation would exceed Integer.MAX_VALUE
        return -1;
    }
}

